export default "import { useState } from \"react\";\nimport { VuiButtonSecondary, VuiDatePicker, VuiSpacer, VuiText } from \"../../../lib\";\n\nexport const DatePicker = () => {\n  const [isOpen, setIsOpen] = useState<boolean>(false);\n  const [date, setDate] = useState<Date | undefined>(new Date());\n\n  return (\n    <>\n      <VuiText>\n        <p>{date?.toUTCString() ?? \"Unknown\"}</p>\n      </VuiText>\n\n      <VuiSpacer size=\"s\" />\n\n      <VuiButtonSecondary\n        color=\"neutral\"\n        onClick={() => {\n          // Add one day to the end date.\n          setDate((prevDate) => {\n            if (!prevDate) return new Date();\n            const newDate = new Date(prevDate);\n            newDate.setDate(newDate.getDate() + 1);\n            return newDate;\n          });\n        }}\n      >\n        Add day to verify external control\n      </VuiButtonSecondary>\n\n      <VuiSpacer size=\"s\" />\n\n      <VuiDatePicker\n        header=\"Pick a date, any date\"\n        date={date}\n        onChange={(date) => setDate(date)}\n        isOpen={isOpen}\n        setIsOpen={setIsOpen}\n        anchorSide=\"left\"\n        canClear\n      />\n    </>\n  );\n};\n";