export default "import { useState } from \"react\";\nimport { AnchorSide, VuiFormGroup, VuiSearchSelect, VuiSelect, VuiSpacer, VuiText, VuiTextInput } from \"../../../lib\";\n\nconst options = [\n  { value: \"a\", label: \"Caffeine-free\" },\n  { value: \"b\", label: \"Freeze dried\" },\n  { value: \"c\", label: \"Gluten-free\" },\n  { value: \"d\", label: \"Halal\" },\n  { value: \"e\", label: \"High fiber\" },\n  { value: \"f\", label: \"Kosher\" },\n  { value: \"g\", label: \"Lactose-free\" },\n  { value: \"h\", label: \"Low-carb\" },\n  { value: \"i\", label: \"No nuts\" },\n  { value: \"j\", label: \"Non-GMO\" },\n  { value: \"k\", label: \"Sugar-free\" },\n  { value: \"l\", label: \"Vegan\" }\n];\n\nconst getOptionForValue = (value: string) => {\n  const option = options.find((option) => option.value === value);\n  return option ? option.label : \"\";\n};\n\nconst humanizeOptions = (values: string[]) => {\n  if (values.length === 0) {\n    return \"None selected\";\n  }\n\n  if (values.length === 1) {\n    return getOptionForValue(values[0]);\n  }\n\n  if (values.length === 2) {\n    return `${getOptionForValue(values[0])} and ${getOptionForValue(values[1])}`;\n  }\n\n  return `${values\n    .slice(0, -1)\n    .map((value) => getOptionForValue(value))\n    .join(\", \")}, and ${getOptionForValue(values[values.length - 1])}`;\n};\n\nexport const FormGroup = () => {\n  const [isOpen, setIsOpen] = useState(false);\n  const [searchValue, setSearchValue] = useState<string>(\"\");\n  const [selectedOptions, setSelectedOptions] = useState<string[]>([]);\n\n    const [anchorSide, setAnchorSide] = useState<AnchorSide | undefined>(\"left\");\n  const anchorOptions = [\n    { text: \"Left\", value: \"left\" },\n    { text: \"Right\", value: \"right\" },\n    { text: \"Right Up\", value: \"rightUp\" },\n    { text: \"Left Up\", value: \"leftUp\" },\n    { text: \"Up Left\", value: \"upLeft\" },\n    { text: \"Up Right\", value: \"upRight\" }\n  ];\n\n\n  return (\n    <>\n    <VuiText size=\"s\">\n      <p>\n        <strong>\n          Popover position\n        </strong>\n      </p>\n    </VuiText>\n    <VuiSpacer size=\"xs\" />\n     <VuiSelect\n        options={anchorOptions}\n        value={anchorSide}\n        onChange={(event) => setAnchorSide(event.target.value as AnchorSide)}\n      />\n      <VuiSpacer size=\"l\" />\n    <VuiFormGroup label=\"Search select\" labelFor=\"searchSelect\">\n      <VuiSearchSelect\n        title=\"Choose one or more\"\n        isOpen={isOpen}\n        setIsOpen={setIsOpen}\n        searchValue={searchValue}\n        setSearchValue={setSearchValue}\n        onSelect={(value: string[]) => {\n          setSelectedOptions(value);\n        }}\n        selectedOptions={selectedOptions}\n        options={options}\n        anchorSide={anchorSide}\n        >\n        <VuiTextInput fullWidth color=\"neutral\" id=\"searchSelect\" value={humanizeOptions(selectedOptions)} />\n      </VuiSearchSelect>\n    </VuiFormGroup>\n        </>\n  );\n};\n";