export default "import { VuiSimpleGrid, VuiPanel, VuiText, VuiTitle, VuiSpacer } from \"../../../lib\";\n\nexport const GridSimple = () => (\n  <>\n    <VuiTitle size=\"s\">\n      <h3>SimpleGrid - Responsive Auto-fit</h3>\n    </VuiTitle>\n\n    <VuiSpacer size=\"m\" />\n\n    <VuiSimpleGrid minChildWidth=\"250px\" spacing=\"m\">\n      {[1, 2, 3, 4, 5, 6, 7, 8].map((i) => (\n        <VuiPanel key={i}>\n          <VuiText>\n            <p>Item {i}</p>\n            <p>Minimum width: 250px</p>\n          </VuiText>\n        </VuiPanel>\n      ))}\n    </VuiSimpleGrid>\n\n    <VuiSpacer size=\"m\" />\n\n    <VuiTitle size=\"s\">\n      <h3>SimpleGrid - Fixed Columns</h3>\n    </VuiTitle>\n\n    <VuiSpacer size=\"m\" />\n\n    <VuiSimpleGrid columns={3} spacing=\"l\">\n      {[1, 2, 3, 4, 5, 6].map((i) => (\n        <VuiPanel key={i}>\n          <VuiText>\n            <p>Item {i}</p>\n            <p>Fixed 3 columns</p>\n          </VuiText>\n        </VuiPanel>\n      ))}\n    </VuiSimpleGrid>\n  </>\n);\n";