export default "import { VuiGrid, VuiGridItem, VuiPanel, VuiText, VuiTitle, VuiSpacer } from \"../../../lib\";\n\nexport const GridAlignment = () => (\n  <>\n    <VuiTitle size=\"s\">\n      <h3>Grid Alignment</h3>\n    </VuiTitle>\n\n    <VuiSpacer size=\"m\" />\n\n    <VuiGrid\n      templateColumns=\"repeat(4, 1fr)\"\n      templateRows=\"100px\"\n      spacing=\"m\"\n      alignItems=\"center\"\n      justifyItems=\"stretch\"\n    >\n      <VuiGridItem justifySelf=\"start\">\n        <VuiPanel>\n          <VuiText>\n            <p>Start</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem justifySelf=\"center\">\n        <VuiPanel>\n          <VuiText>\n            <p>Centered</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem justifySelf=\"stretch\">\n        <VuiPanel>\n          <VuiText>\n            <p>Stretched</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem justifySelf=\"end\">\n        <VuiPanel>\n          <VuiText>\n            <p>End</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem>\n        <VuiPanel>\n          <VuiText>\n            <p>Stretched</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem>\n        <VuiPanel>\n          <VuiText>\n            <p>Stretched</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem>\n        <VuiPanel>\n          <VuiText>\n            <p>Stretched</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n\n      <VuiGridItem>\n        <VuiPanel>\n          <VuiText>\n            <p>Stretched</p>\n          </VuiText>\n        </VuiPanel>\n      </VuiGridItem>\n    </VuiGrid>\n  </>\n);\n";