import classNames from "classnames";
import { useVuiContext } from "../context/Context";

export type TabProps = {
  children: React.ReactNode;
  className?: string;
  href?: string;
  onClick?: () => void;
  isActive?: boolean;
  // Passed through so consumers can implement the WAI-ARIA tab pattern, which needs
  // roles, a roving tabindex, and a tab-to-panel association.
  id?: string;
  role?: string;
  tabIndex?: number;
  "aria-selected"?: boolean;
  "aria-controls"?: string;
};

export const VuiTab = ({ children, className, href, onClick, isActive = false, ...rest }: TabProps) => {
  const { createLink } = useVuiContext();

  const classes = classNames(className, "vuiTab", {
    "vuiTab-isActive": isActive
  });

  const content = <div className="vuiTab__inner">{children}</div>;

  if (href) {
    return createLink({
      className: classes,
      href,
      onClick,
      children: content,
      ...rest
    });
  }

  return (
    <button className={classes} onClick={onClick} type="button" {...rest}>
      {content}
    </button>
  );
};
