export default "import { BiCompass } from \"react-icons/bi\";\nimport { VuiPatch, VuiFlexContainer, VuiIcon } from \"../../../lib\";\n\nconst sizes = [\"xs\", \"s\", \"m\"] as const;\n\nexport const Sizes = () => {\n  return (\n    <VuiFlexContainer spacing=\"m\" wrap>\n      {sizes.map((size) => (\n        <div>\n          <VuiPatch color=\"primary\" size={size}>\n            <VuiIcon>\n              <BiCompass />\n            </VuiIcon>\n          </VuiPatch>\n        </div>\n      ))}\n    </VuiFlexContainer>\n  );\n};\n";